const std::vector<TonalAdvice>& tonalAdvice()
{
    static const std::vector<TonalAdvice> v {
        { "Низ гудит в машине и в клубе. Лимитер работает больше.", { "Multiband, полоса Low: уменьшите Thresh, пока кольцо не станет красным на ударах бочки.", "Dynamic EQ: Low shelf 60 Hz, −1…−2 dB.", "Input: поднимите Subsonic до 30–35 Hz." }, "Низ звучит слабо на больших системах.", { "Dynamic EQ: Low shelf 50 Hz, +1…+2 dB.", "Input: опустите Subsonic до 20–25 Hz.", "Multiband, полоса Low: увеличьте Thresh." } },
        { "Бас и бочка закрывают гитары. Звук мутный.", { "Dynamic EQ: Bell 100 Hz, Q 1.0, −1…−2 dB. Включите Dynamic: полоса работает только на громких нотах.", "Multiband, полоса Low-mid: уменьшите Thresh, Ratio 2:1." }, "Микс звучит тонко. Удар бочки слабый.", { "Dynamic EQ: Bell 100 Hz, Q 1.0, +1…+2 dB.", "Saturation, полоса Low: Drive 2–4 dB. Гармоники делают бас слышнее." } },
        { "Звук мутный и «картонный».", { "Dynamic EQ: Bell 250–300 Hz, Q 1.5, −1…−2 dB.", "Multiband, полоса Low-mid: уменьшите Thresh." }, "Гитары звучат тонко. Нет «тела».", { "Dynamic EQ: Bell 250 Hz, Q 1.0, +1 dB.", "Saturation, полоса Mid: Drive 1–3 dB, тип Tape." } },
        { "Звук «в нос», плоский и громкий.", { "Dynamic EQ: Bell 800 Hz – 1 kHz, Q 1.0, −1 dB.", "Multiband, полоса Mid: уменьшите Thresh, Ratio 1.5:1." }, "Вокал и соло-гитара уходят назад.", { "Dynamic EQ: Bell 1 kHz, Q 0.8, +1 dB.", "Saturation, полоса Mid: Drive 1–2 dB." } },
        { "Гитары режут уши. Звук утомляет.", { "Dynamic EQ: Bell 3–4 kHz, Q 2.0, −1…−2 dB. Включите Dynamic.", "Resonance suppressor: Low 2 kHz, High 6 kHz, Depth 3–6 dB.", "Saturation, полоса High: уменьшите Drive." }, "Гитары и вокал не читаются. Звук глухой.", { "Dynamic EQ: Bell 3 kHz, Q 1.0, +1 dB.", "Resonance suppressor: уменьшите Depth." } },
        { "Тарелки шипят. Звук резкий.", { "Dynamic EQ: High shelf 10 kHz, −1 dB.", "Resonance suppressor: High 16 kHz, Depth 3 dB.", "Saturation, полоса High: уменьшите Drive или Mix." }, "Звук тёмный. Тарелки плохо слышно.", { "Dynamic EQ: High shelf 10 kHz, +1…+1.5 dB.", "Resonance suppressor: уменьшите Depth или High." } },
    };
    return v;
}

const std::vector<BandAdvice>& multibandAdvice()
{
    static const std::vector<BandAdvice> v {
        { "mb.thresh", { "Здесь бочка и бас ниже 80 Hz. Ставьте порог так, чтобы кольцо краснело только на ударах бочки.", "Здесь «тело» баса и удар бочки. Сжатие на 1–2 dB делает низ ровнее.", "Здесь основа гитар и вокала. Ставьте высокий порог: эта полоса должна сжиматься редко.", "Здесь атака гитар и щелчок малого. Порог ниже на 2–4 dB убирает резкие всплески.", "Здесь тарелки. Ставьте порог так, чтобы сжатие было только на крэшах." } },
        { "mb.ratio", { "Используйте 2:1–4:1. Так бас звучит ровно на всех нотах.", "Используйте 1.5:1–3:1. Большое значение делает удар бочки слабее.", "Используйте 1.5:1–2:1. Большое значение делает гитары плоскими.", "Используйте 2:1–3:1, чтобы убрать резкость атак.", "Используйте 1.5:1–2:1. Большое значение делает тарелки тусклыми." } },
        { "mb.makeup", { "Поднимите на величину GR. Лишний подъём забирает запас лимитера.", "Компенсируйте GR. Лишний подъём делает микс мутным.", "Компенсируйте GR. Подъём на 1 dB выводит гитары вперёд.", "Не поднимайте больше GR: звук станет резким.", "Небольшой подъём добавляет «воздух» после сжатия." } },
        { "mb.attack", { "Медленная атака 20–40 ms пропускает удар бочки.", "Атака 10–30 ms сохраняет удар бочки и щипок баса.", "Атака 10–20 ms. Быстрая атака делает гитары плоскими.", "Быстрая атака 1–5 ms убирает резкие щелчки.", "Атака 1–5 ms ловит удары по тарелкам." } },
        { "mb.release", { "Медленный отпуск 150–300 ms или Auto. Быстрый отпуск даёт искажения на низе.", "Отпуск 100–200 ms. Сжатие должно уйти до следующего удара бочки.", "Отпуск 100–200 ms или Auto.", "Отпуск 50–120 ms возвращает яркость между ударами.", "Отпуск 50–100 ms. Медленный отпуск делает тарелки тусклыми." } },
        { "mb.knee", { "Мягкое колено 6–10 dB делает работу незаметной.", "Колено 6 dB подходит в большинстве случаев.", "Мягкое колено 8–12 dB даёт прозрачное сжатие.", "Колено 3–6 dB точнее ловит всплески.", "Колено около 6 dB." } },
        { "mb.mix", { "100% даёт ровный низ. Меньше — сохраняет естественный удар.", "Используйте 70–100%.", "50–80% сохраняет живость гитар.", "100% даёт полный контроль резкости.", "Используйте 70–100%." } },
        { "mb.link", { "100%: низ остаётся в центре.", "100% держит бас в центре.", "50–100%. Меньше — гитары шире, но центр может смещаться.", "Используйте 50–100%.", "50–80% сохраняет ширину тарелок." } },
        { "mb.trim", { "−1 dB уменьшает гул.", "−1 dB убирает муть, +1 dB добавляет тело.", "Меняет баланс гитар и вокала в миксе.", "−1 dB уменьшает резкость, +1 dB даёт разборчивость.", "+1 dB добавляет «воздух», −1 dB убирает шипение." } },
    };
    return v;
}
